import { CtaBand } from "march/landing"

// beşlik bandı: her basışta sayaç artar, başlık ve not kendiliğinden güncellenir (title ve note işlev olabilir)
export function HighFive() {
  let $fives = 0
  return <CtaBand variant="mesh" reveal="none"
    title={() => ($fives ? `${$fives} beşlik çakıldı ✋` : "Bir beşlik çak!")}
    lead="Gün boyu iyi iş çıkardın."
    actions={[{ label: "✋ Çak", onClick: () => $fives++ }]}
    note={() => ($fives >= 5 ? "Efsane oldun 🏆" : `Efsaneye ${5 - $fives} kaldı`)} />
}

import { CtaBand } from "march/landing"
import { toast } from "march/ui"
import { arrowRight, phone } from "march/icons"

// bir spor salonunun sayfa sonu çağrısı: ilk ay ücretsiz deneme ve telefonla bilgi
export function GymTrial() {
  return <CtaBand variant="gradient" title="İlk ay bizden"
    lead="Ekipman, grup dersleri ve havuz dahil. Sözleşme yok, istediğin an bırak."
    actions={[
      { label: "Ücretsiz dene", iconEnd: arrowRight, onClick: () => toast("Deneme üyeliğin oluşturuldu") },
      { label: "Bizi ara", icon: phone, href: "tel:+902120000000", variant: "secondary" },
    ]}
    note="Kart bilgisi istemiyoruz · Kadıköy ve Beşiktaş şubeleri" />
}

import { CtaBand } from "march/landing"
import { Segmented, Toggle, Card, Button } from "march/ui"
import { arrowRight, play } from "march/icons"

// CtaBand'in bütün özellikleri bir arada: başlık, açıklama, eylemler (nesne ya da düğüm), not, beş arka plan, video,
// hiza, süs katmanları, giriş hareketi ve sınıf
const VARIANTS = [{ value: "gradient", label: "gradyan" }, { value: "mesh", label: "ağ" }, { value: "glass", label: "cam" }, { value: "plain", label: "sade" }, { value: "video", label: "video" }]

export function CtaBandLab() {
  let $variant = "gradient"
  let $start = false
  let $backdrop = true
  let $motion = false
  let $joined = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Arka plan" options={VARIANTS} bind:value={$variant} />
        <Toggle label="Başa hizala" bind:value={$start} />
        <Toggle label="Süs katmanları" bind:value={$backdrop} />
        <Toggle label="Giriş hareketi" bind:value={$motion} />
      </div>
    </Card>
    {() => {
      // sinyaller burada okunur: değişince bant yeniden çizilir (başlık ve not işlev: kendiliğinden güncellenir)
      const variant = $variant, start = $start, backdrop = $backdrop, motion = $motion
      return <CtaBand class="lab-cta" variant={variant as "gradient"} align={start ? "start" : "center"} backdrop={backdrop}
        reveal={motion ? "blur" : "none"} video={{ src: "/media/hadi-waves.webm", poster: "/media/hadi-waves.jpg" }}
        title={() => `Bugün ${$joined} kişi katıldı`} lead="Sen de aramıza katıl, ilk hafta ücretsiz."
        actions={[
          { label: "Katıl", iconEnd: arrowRight, onClick: () => $joined++ },
          { label: "Tanıtım", icon: play, variant: "secondary" },
          <Button variant="link" href="#sss" class="lab-faq">Sık sorulanlar</Button> as Node,
        ]}
        note={() => ($joined ? "Teşekkürler!" : "Kart gerekmez")} />
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { CtaBandLab } from "./CtaBandLab.tsx"

// CtaBandLab'in testleri: kaydedince Testler sekmesinde çalışır
test("gradyan bant: başlık, açıklama, not ve düğüm eylem", () => {
  const s = renderTest(() => <CtaBandLab />)
  expect(s.get(".lab-cta")?.classList.contains("m-cta-gradient")).toBeTruthy()
  expect(s.find("Bugün 0 kişi katıldı")).not.toBe(null)
  expect(s.find("Sen de aramıza katıl, ilk hafta ücretsiz.")).not.toBe(null)
  expect(s.find("Kart gerekmez")).not.toBe(null)
  expect(s.get('.lab-cta a.lab-faq[href="#sss"]')).not.toBe(null)
})

test("Katıl: başlık ve not kendiliğinden güncellenir", async () => {
  const s = renderTest(() => <CtaBandLab />)
  await s.click("Katıl")
  expect(s.find("Bugün 1 kişi katıldı")).not.toBe(null)
  expect(s.find("Teşekkürler!")).not.toBe(null)
})

test("ağ görünümüne geçer", async () => {
  const s = renderTest(() => <CtaBandLab />)
  await s.click("ağ")
  expect(s.get(".lab-cta")?.classList.contains("m-cta-mesh")).toBeTruthy()
})

test("süs katmanları kapanınca panelde katman kalmaz", async () => {
  const s = renderTest(() => <CtaBandLab />)
  expect(s.all(".lab-cta .m-cta-panel > .m-ov").length).toBeGreaterThan(0)
  await s.click("Süs katmanları")
  expect(s.all(".lab-cta .m-cta-panel > .m-ov").length).toBe(0)
})
